import re
from collections import deque


def parse_script(text: str) -> dict:
    """
    Parse a dialogue script into a structured graph with nodes and edges.

    Returns a dict with keys 'nodes' and 'edges'.
    """
    nodes = {}       # id -> node dict
    edges = []        # list of edge dicts
    node_order = []   # preserve order of node appearance

    # Split into sections by [SectionName] headers
    # Pattern: [SomeID] at the start of a line
    sections = re.split(r'\n(?=\[)', text.strip())

    for section in sections:
        section = section.strip()
        if not section:
            continue

        lines = section.split('\n')
        header_line = lines[0].strip()
        m = re.match(r'^\[(.+)\]$', header_line)
        if not m:
            continue

        node_id = m.group(1)
        content_lines = [l.strip() for l in lines[1:] if l.strip()]

        if not content_lines:
            continue

        # Determine node type: if first content line starts with a number + dot, it's a choice
        first_line = content_lines[0]
        choice_match = re.match(r'^(\d+)\.\s', first_line)

        if choice_match:
            # Choice node
            nodes[node_id] = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }
            node_order.append(node_id)

            for line in content_lines:
                cm = re.match(r'^\d+\.\s+(.*?)\s*->\s*(\S+)$', line)
                if cm:
                    choice_text = cm.group(1).strip()
                    target = cm.group(2).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": choice_text
                    })
        else:
            # Line node: "Speaker: dialogue text -> target"
            lm = re.match(r'^([^:]+):\s*(.*?)\s*->\s*(\S+)$', first_line)
            if lm:
                speaker = lm.group(1).strip()
                dialogue_text = lm.group(2).strip()
                target = lm.group(3).strip()

                nodes[node_id] = {
                    "id": node_id,
                    "text": dialogue_text,
                    "speaker": speaker,
                    "type": "line"
                }
                node_order.append(node_id)

                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": ""
                })

    # Add implicit "End" node if referenced but not defined
    all_edge_targets = {e["to"] for e in edges}
    for target in all_edge_targets:
        if target not in nodes:
            nodes[target] = {
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            }
            node_order.append(target)

    # BFS from "Start" to find reachable nodes
    start = "Start"
    reachable = set()
    if start in nodes:
        q = deque([start])
        while q:
            node = q.popleft()
            if node in reachable:
                continue
            reachable.add(node)
            for edge in edges:
                if edge["from"] == node and edge["to"] not in reachable:
                    q.append(edge["to"])

    # Filter to only reachable nodes and edges
    filtered_nodes = []
    for nid in node_order:
        if nid in reachable:
            filtered_nodes.append(nodes[nid])

    filtered_edges = [
        e for e in edges
        if e["from"] in reachable and e["to"] in reachable
    ]

    return {
        "nodes": filtered_nodes,
        "edges": filtered_edges
    }


def generate_dot(graph: dict) -> str:
    """Generate a Graphviz DOT representation of the dialogue graph."""
    lines = ['digraph Dialogue {']
    lines.append('    rankdir=TB;')
    lines.append('    node [fontname="Helvetica"];')
    lines.append('    edge [fontname="Helvetica"];')

    for node in graph["nodes"]:
        nid = node["id"]
        ntype = node["type"]
        speaker = node.get("speaker", "")
        text = node.get("text", "")

        # Escape special characters for DOT
        label_text = text.replace('"', '\\"').replace('\n', ' ')
        speaker_esc = speaker.replace('"', '\\"')

        if nid == "End":
            shape = "doublecircle"
        elif ntype == "choice":
            shape = "diamond"
        else:
            shape = "box"

        if ntype == "choice":
            label = f"{nid}"
        elif nid == "End":
            label = "End"
        else:
            label = f"{speaker_esc}: {label_text}"

        label = label.replace('"', '\\"')
        # Truncate long labels for readability
        if len(label) > 80:
            label = label[:77] + "..."

        lines.append(f'    "{nid}" [shape={shape}, label="{label}"];')

    for edge in graph["edges"]:
        src = edge["from"]
        dst = edge["to"]
        etext = edge["text"].replace('"', '\\"').replace('\n', ' ')
        if len(etext) > 60:
            etext = etext[:57] + "..."
        if etext:
            lines.append(f'    "{src}" -> "{dst}" [label="{etext}"];')
        else:
            lines.append(f'    "{src}" -> "{dst}";')

    lines.append('}')
    return '\n'.join(lines)


if __name__ == '__main__':
    with open('/app/script.txt', 'r') as f:
        script_content = f.read()

    graph = parse_script(script_content)

    with open('/app/dialogue.json', 'w') as f:
        json.dump(graph, f, indent=2)

    dot_content = generate_dot(graph)
    with open('/app/dialogue.dot', 'w') as f:
        f.write(dot_content)

    print(f"Parsed {len(graph['nodes'])} nodes and {len(graph['edges'])} edges")
    print(f"Node types: {sum(1 for n in graph['nodes'] if n['type'] == 'line')} line, {sum(1 for n in graph['nodes'] if n['type'] == 'choice')} choice")
    print("Output written to /app/dialogue.json and /app/dialogue.dot")", "path": "/app/solution.py"}: Editing /app/solution.py

